declare(strict_types=1);require_once __DIR__.'/legacy-migration/MigratedEvidenceProjectionStore.php';function projectionEnv(string$n):string{$v=getenv($n);if(!is_string($v)||$v==='')throw new RuntimeException("Missing {$n}");return$v;}$apply=in_array('--apply',$argv,true);$manifest=json_decode((string)file_get_contents(projectionEnv('FMONITOR_PILOT_ACTIVE_MANIFEST')),true,flags:JSON_THROW_ON_ERROR);$p=(string)($manifest['processPrefix']??'');$db=new mysqli(projectionEnv('FMONITOR_DB_HOST'),projectionEnv('FMONITOR_DB_USER'),projectionEnv('FMONITOR_DB_PASSWORD'),projectionEnv('FMONITOR_DB_NAME'),(int)projectionEnv('FMONITOR_DB_PORT'));$db->set_charset('utf8mb4');try{$count=(int)$db->query("SELECT COUNT(*) n FROM `{$p}fm2_history_source_snapshots` s WHERE NOT EXISTS(SELECT 1 FROM `{$p}fm2_history_source_snapshots` n WHERE n.legacy_object_id=s.legacy_object_id AND n.id>s.id)")->fetch_assoc()['n'];if(!$apply){echo json_encode(['mode'=>'dry-run','scanned'=>$count,'writes'=>0]),"\n";exit;}$legacy=MigratedEvidenceReconciliation::load($db,$p);$expected=[];foreach($legacy as $row)$expected[(int)$row["snapshotId"]]=$row["projectionHash"];$db->begin_transaction();try{$result=(new MigratedEvidenceProjectionStore($db,$p))->backfill(gmdate('Y-m-d H:i:s'));$actual=[];foreach($db->query("SELECT snapshot_id,projection_sha256 FROM `{$p}fm2_migrated_evidence_projection`")->fetch_all(MYSQLI_ASSOC)as$row)$actual[(int)$row["snapshot_id"]]=$row["projection_sha256"];ksort($expected);ksort($actual);if($expected!==$actual)throw new RuntimeException("Projection differential mismatch");$result["differentialMatched"]=count($actual);$db->commit();echo json_encode(['mode'=>'apply']+$result),"\n";}catch(Throwable$e){$db->rollback();throw$e;}}finally{$db->close();}
